create or replace view public.registry_unresolved_relationship_endpoints with (security_invoker = true) as select id as relationship_id, case when source_entity_id is null then 'source' else 'target' end as missing_side, case when source_entity_id is null then source_entity_type else target_entity_type end as missing_entity_type, case when source_entity_id is null then source_slug else target_slug end as legacy_slug, relationship_type, relationship_role, source_entity_id, target_entity_id from public.registry_entity_relationships where relationship_status <> 'archived' and (source_entity_id is null or target_entity_id is null);;
